function columns_getColumnIcon(column) {
    if (Lib.isPrimaryKey(column)) {
        return "label";
    }
    if (Lib.isForeignKey(column)) {
        return "connections";
    }
    if (Lib.isLocation(column) || Lib.isLatitude(column) || Lib.isLongitude(column)) {
        return "location";
    }
    if (Lib.isTemporal(column)) {
        return "calendar";
    }
    // Wide type checks should go last,
    // as PK/FK/Location/Date, etc. are also strings, numbers, etc.
    if (Lib.isBoolean(column)) {
        return "io";
    }
    if (Lib.isStringOrStringLike(column)) {
        return "string";
    }
    if (Lib.isNumeric(column)) {
        return "int";
    }
    return "list";
}

